#[path="/Users/nk/Desktop/ducksmiles-analytics-20261021/crates/analytics/src/irt.rs"]
mod irt;
#[no_mangle]
unsafe extern "C" fn candidate_irt_run(op:*const u8,op_len:usize,data:*const f64,n:usize,p:usize,args:*const f64,k:usize,out:*mut usize)->*mut u8 {
 if out.is_null(){return std::ptr::null_mut();}*out=0;
 if op.is_null()||data.is_null()||n==0||p==0||n>10000||p>128||n>1_000_000/p||k>16384||(k>0&&args.is_null()){return std::ptr::null_mut();}
 let operation=match std::str::from_utf8(std::slice::from_raw_parts(op,op_len)){Ok(x)=>x,Err(_)=>return std::ptr::null_mut()};
 let flat=std::slice::from_raw_parts(data,n*p);let rows=flat.chunks_exact(p).map(|r|r.to_vec()).collect::<Vec<_>>();let params=if k==0{&[]}else{std::slice::from_raw_parts(args,k)};
 match irt::run(operation,&rows,params){Ok(j)=>{let mut bytes=j.into_bytes().into_boxed_slice();*out=bytes.len();let pointer=bytes.as_mut_ptr();std::mem::forget(bytes);pointer},Err(_)=>std::ptr::null_mut()}
}
#[no_mangle]
unsafe extern "C" fn candidate_irt_free(pointer:*mut u8,len:usize){if !pointer.is_null(){drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(pointer,len)));}}
